package com.marketplace.productservice;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.cache.annotation.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.net.URI; import java.util.*;
interface ProductRepository extends JpaRepository<Product,Long>{} @RestController @RequestMapping("/api/products") class ProductController { private final ProductRepository repo; ProductController(ProductRepository r){repo=r;} record Request(@NotBlank String name,@NotNull @Positive BigDecimal price,@PositiveOrZero int stock){} @GetMapping @Cacheable("products") List<Product> list(){return repo.findAll();}@GetMapping("/{id}") @Cacheable(value="product",key="#id") Product get(@PathVariable Long id){return repo.findById(id).orElseThrow();}@PostMapping ResponseEntity<Product> create(@Valid @RequestBody Request r){var p=repo.save(new Product(r.name(),r.price(),r.stock()));return ResponseEntity.created(URI.create("/api/products/"+p.id)).body(p);}@PutMapping("/{id}") @CacheEvict(value={"product","products"},allEntries=true) Product update(@PathVariable Long id,@Valid @RequestBody Request r){var p=repo.findById(id).orElseThrow();p.name=r.name();p.price=r.price();p.stock=r.stock();return repo.save(p);} }
